"""Named-response fallback for ``HookRejection`` at the outgoing-text point.

``rasa.mantle.hooks.outgoing_text`` runs observers and modifiers. Resolving a
``responses.yml`` name is orchestration: it needs the per-turn
:class:`~rasa.mantle.orchestration.skill_executor.SkillExecutor` the processor
already built from :class:`~rasa.mantle.model_archive.bootstrap.ModelBootstrap`.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Mapping, Optional

import structlog

from rasa.mantle.content.responses import ResponseDefinition, ResponseRegistry
from rasa.mantle.hooks.constants import UTTER_OUTGOING_TEXT_REJECTED
from rasa.mantle.hooks.outgoing_text import OutgoingRejectionFallback

if TYPE_CHECKING:
    from rasa.mantle.orchestration.skill_executor import SkillExecutor
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()

# Last-resort copy when even the packaged template cannot be read. Must never
# be an ``utter_*`` name — those leak into the user-visible channel.
_LAST_RESORT_OUTGOING_REJECTED_TEXT = (
    "I'm sorry, but I can't provide that response. Please try again."
)


def _fallback_from_variant(
    *,
    resolved_name: str,
    variant: ResponseDefinition | None,
) -> OutgoingRejectionFallback:
    """Build a user-visible fallback without re-reading tracker memory."""
    text = (
        variant.text.strip()
        if variant is not None and variant.text.strip()
        else _LAST_RESORT_OUTGOING_REJECTED_TEXT
    )
    if variant is None:
        return OutgoingRejectionFallback(
            text=text,
            response_name=resolved_name,
        )
    return OutgoingRejectionFallback(
        text=text,
        buttons=variant.buttons,
        variant_metadata=variant.metadata or None,
        response_name=resolved_name,
    )


def _select_outgoing_rejection_variant(
    *,
    response_message: Optional[str],
    response_registry: ResponseRegistry,
    memory_values: Mapping[str, object],
) -> tuple[str, ResponseDefinition | None]:
    """Pick a registry variant, falling back to the packaged reject template."""
    resolved_name = response_message or UTTER_OUTGOING_TEXT_REJECTED
    variant = response_registry.select_variant(resolved_name, memory_values)
    if variant is None:
        if resolved_name != UTTER_OUTGOING_TEXT_REJECTED:
            structlogger.warning(
                "mantle.hooks.outgoing_text.response_not_found",
                response_name=resolved_name,
                fallback_response_name=UTTER_OUTGOING_TEXT_REJECTED,
                in_registry=resolved_name in response_registry.responses,
            )
        resolved_name = UTTER_OUTGOING_TEXT_REJECTED
        variant = response_registry.select_variant(resolved_name, memory_values)
    return resolved_name, variant


def resolve_outgoing_rejection_fallback(
    *,
    response_message: Optional[str] = None,
    skill_executor: "SkillExecutor",
    tracker_handle: "TrackerHandle",
    response_registry: ResponseRegistry,
) -> OutgoingRejectionFallback:
    """Resolve the user-visible reply for a rejected outgoing utterance.

    ``response_message`` is a ``responses.yml`` name, never free-form text.
    Missing names, unknown names, and names whose conditioned variants all
    miss fall back to the packaged ``utter_outgoing_text_rejected``. Resolve
    failures never surface an ``utter_*`` name as the spoken text.
    """
    memory_available = True
    try:
        memory_values = skill_executor.current_memory_values(tracker_handle)
    except Exception as exc:
        structlogger.warning(
            "mantle.hooks.outgoing_text.memory_unavailable",
            error_type=type(exc).__name__,
        )
        memory_values = {}
        memory_available = False

    resolved_name, variant = _select_outgoing_rejection_variant(
        response_message=response_message,
        response_registry=response_registry,
        memory_values=memory_values,
    )

    if not memory_available:
        # ``resolve_response_name`` re-reads memory; skip it after a failed lookup.
        return _fallback_from_variant(resolved_name=resolved_name, variant=variant)

    try:
        utterance = skill_executor.resolve_response_name(resolved_name, tracker_handle)
    except Exception as exc:
        structlogger.warning(
            "mantle.hooks.outgoing_text.response_resolve_failed",
            response_name=resolved_name,
            error_type=type(exc).__name__,
        )
        return _fallback_from_variant(resolved_name=resolved_name, variant=variant)

    if utterance.text.strip() == resolved_name:
        # ``SkillExecutor.resolve_response_name`` uses the name as template text
        # when variant selection misses; never deliver that to the user.
        return _fallback_from_variant(resolved_name=resolved_name, variant=variant)

    return OutgoingRejectionFallback(
        text=utterance.text,
        buttons=utterance.buttons,
        variant_metadata=utterance.variant_metadata,
        response_name=resolved_name,
    )
